mapper.select:
select ccc.cashflow_id,hbm.bp_name bp_name_tenant, vip.invoice_profile billing_method, (select v.description from vat_invoice_profile v where v.invoice_profile = vip.invoice_profile) billing_method_n, cc.billing_method,ccc.times,cc.contract_id,ccc.cashflow_id cashflow_ids, pp.project_id, hbm.bp_id,hbm.bp_name bp_id_n, vip.invoice_kind, hbm.invoice_title bp_name, cba.bp_tax_registry_num bp_tax_registry_num, cba.bp_address_phone_num bp_address_phone_num, cba.bp_bank_account bp_bank_account, hbm.TAXPAYER_TYPE, aiht.invoice_date,aiht.billing_way, aiht.invoice_hd_temp_id, aiht.DESCRIPTION, aiht.billing_type, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_KIND' AND vip.invoice_kind = v.code_value ) invoice_kind_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.BILLING_WAY' AND aiht.billing_way = v.code_value ) billing_way_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HLS211_TAXPAYER_TYPE' AND hbm.taxpayer_type = v.code_value ) taxpayer_type_n, (case when (select count(1) from con_contract_cashflow cf where cf.cashflow_id in
#{cashflowId}
and (cf.write_off_flag = 'NOT' or cf.write_off_flag = 'PARTIAL')) = 0 then '核销' when (select count(1) from con_contract_cashflow cf where cf.cashflow_id in
#{cashflowId}
and (cf.write_off_flag = 'FULL' or cf.write_off_flag = 'PARTIAL')) = 0 then '未核销' else '部分核销' end) write_off_flag_n from con_contract_cashflow ccc left join con_contract cc on cc.contract_id = ccc.contract_id LEFT JOIN prj_project pp ON pp.project_id = cc.project_id left join con_contract_bank_account cba on cba.contract_id = ccc.contract_id left join vat_invoice_profile_dtl vip on (case when (cc.business_type='LEASE' and cc.lease_item_property='MOVABLE') THEN 'LEASE_MOVABLES' when (cc.business_type='LEASE' and cc.lease_item_property='IMMOVABLE') THEN 'LEASE_IMMOVABLES' when (cc.business_type='LEASEBACK' and cc.lease_item_property='MOVABLE') THEN 'LEASEBACK_MOVABLES' when (cc.business_type='LEASEBACK' and cc.lease_item_property='IMMOVABLE') THEN 'LEASEBACK_IMMOVABLES' else '' end) = vip.invoice_profile and ccc.cf_item = (case when vip.cf_item = 101 then 1 else vip.cf_item end) and vip.enabled_flag = 'Y' left join acr_invoice_hd_temp aiht on aiht.invoice_hd_temp_id = #{tempId} and aiht.cashflow_id = ccc.cashflow_id left join hls_bp_master hbm on hbm.bp_id = cc.tenant_id
where ccc.cashflow_id in
#{cashflowId}

SELECT ccc.cashflow_id, cc.contract_name, cc.contract_number, aih.invoice_hd_id, aih.bp_name, aih.invoice_kind, aih.total_amount, aih.invoice_date, aih.invoice_number, aih.document_number, CASE aih.invoice_kind WHEN 0 THEN '增值税专用发票' ELSE '增值税普通发票' END AS invoiceKindDesc, ail.times, ail.cf_item, ail.total_amount AS lnTotalAmount, ail.tax_type_rate, ail.tax_amount, hci.description AS cfItemDesc FROM con_contract_cashflow ccc, con_contract cc, acp_invoice_hd aih, acp_invoice_ln ail, hls_cashflow_item hci
cc.contract_id = ccc.contract_id AND ail.cashflow_id = ccc.cashflow_id AND aih.invoice_hd_id = ail.invoice_hd_id AND hci.cf_item = ail.cf_item AND hci.cf_type = ail.cf_type
AND #{invoiceDate} > aih.invoice_date
AND ail.cf_item = #{cfItem}
AND (cc.contract_name LIKE concat('%', #{contractNameOrNumber}, '%') OR cc.contract_number LIKE concat('%', #{contractNameOrNumber}, '%'))
AND ail.times BETWEEN #{timesFrom} AND #{timesTo}
AND aih.total_amount BETWEEN #{iamountFrom} AND #{iamountTo}

SELECT DISTINCT t1.receiptHdId, t1.receiptLnId, t1.cashflowId, t1.bpName, t1.receiptDate, t1.totalAmount, t1.companyName, t1.documentNumber, t1.cfItemDesc, t1.contractNumber, t1.times FROM (SELECT arh.receipt_hd_id AS receiptHdId, arl.receipt_ln_id AS receiptLnId, ccc.cashflow_id AS cashflowId, hbm.bp_name AS bpName, arh.receipt_date AS receiptDate, arl.amount AS totalAmount, com.company_full_name AS companyName, arh.document_number AS documentNumber, CASE ccc.cf_item WHEN 1 THEN '回租本金' ELSE '保证金' END AS cfItemDesc, cc.contract_number contractNumber, ccc.times FROM acr_receipt_hd arh, acr_receipt_ln arl, con_contract_cashflow ccc, con_contract cc, hls_bp_master hbm, fnd_company com WHERE arh.receipt_hd_id = arl.receipt_hd_id AND arl.source_id = ccc.cashflow_id AND ccc.contract_id = cc.contract_id AND arl.source_type = 'CON_CONTRACT' AND cc.company_id = arh.company_id AND arh.bp_id = hbm.bp_id AND com.company_id = cc.company_id AND to_days(#{invoiceDate}) >= to_days(arh.receipt_date)
AND (cc. contract_number LIKE concat('%', #{receiptNameOrNumber}, '%') OR cc.contract_name LIKE concat('%', #{receiptNameOrNumber}, '%') OR hbm.bp_name LIKE concat('%', #{receiptNameOrNumber}, '%'))
AND arh.total_amount BETWEEN #{amountFrom} AND #{amountTo}
AND ccc.cf_item=#{itemFlag}
UNION SELECT arh.receipt_hd_id AS receiptHdId, arl.receipt_ln_id AS receiptLnId, fqc.quotation_cashflow_id AS cashflowId, hbm.bp_name AS bpName, arh.receipt_date AS receiptDate, arl.amount AS totalAmount, com.company_full_name AS companyName, arh.document_number AS documentNumber, CASE fqc.cf_item WHEN 54 THEN '保理本金' ELSE '保证金' END AS cfItemDesc, fc.contract_number contractNumber, fqc.times FROM acr_receipt_hd arh, acr_receipt_ln arl, fct_quotation_cashflow fqc, fct_contract fc, hls_bp_master hbm, fnd_company com WHERE arh.receipt_hd_id = arl.receipt_hd_id AND fqc.contract_id = fc.contract_id AND arl.source_id = fqc.quotation_cashflow_id AND arl.source_type = 'FCT_CONTRACT' AND fc.company_id = arh.company_id AND arh.bp_id = hbm.bp_id AND fc.company_id = com.company_id
AND to_days(#{invoiceDate}) >= to_days(arh.receipt_date)
AND (fc.contract_number LIKE concat('%', #{receiptNameOrNumber}, '%') OR fc.contract_name LIKE concat('%', #{receiptNameOrNumber}, '%') OR hbm.bp_name LIKE concat('%', #{receiptNameOrNumber}, '%'))
AND arh.total_amount BETWEEN #{amountFrom} AND #{amountTo}
AND fqc.cf_item=51
AND fqc.cf_item=40 ) t1 where 1=1
AND t1.receiptLnId=#{receiptLnId}
order by t1.receiptDate desc

SELECT fqc.quotation_cashflow_id AS quotationCashflowId, fc.contract_id, fqc.cf_item AS cfItem, hci.description AS cfItemDesc, scvb.DESCRIPTION AS description, vipd.invoice_kind AS invoiceKind, vipd.taxable_service_name AS taxableServiceName, fttc.description AS taxTypeCodeDescription, CASE WHEN fqc.cf_item=55 THEN interest.invoice_title WHEN fqc.cf_item=57 THEN fee.invoice_title ELSE '' END AS invoiceTitle, fttc.tax_type_rate, CASE WHEN fqc.cf_item=55 THEN ( CASE WHEN interest.three_certificates = 'Y' THEN interest.register_cert_num WHEN (interest.three_certificates = 'N' OR interest.three_certificates IS NULL) THEN interest.tax_registry_num END) WHEN fqc.cf_item=57 THEN ( CASE WHEN fee.three_certificates = 'Y' THEN fee.register_cert_num WHEN (fee.three_certificates = 'N' OR fee.three_certificates IS NULL) THEN fee.tax_registry_num END) ELSE '' END AS bpTaxRegistryNum, CASE WHEN fqc.cf_item=55 THEN interest.invoice_bp_address_phone_num WHEN fqc.cf_item=57 THEN fee.invoice_bp_address_phone_num ELSE '' END AS bpAddressPhoneNum, CASE WHEN fqc.cf_item=55 THEN interest.invoice_bp_bank_account WHEN fqc.cf_item=57 THEN fee.invoice_bp_bank_account ELSE '' END AS bpBankAccount, CASE WHEN fqc.cf_item=55 THEN interest.bp_id WHEN fqc.cf_item=57 THEN fee.bp_id ELSE 0 END AS bp_id, CASE WHEN fqc.cf_item=55 THEN interest.bp_name WHEN fqc.cf_item=57 THEN fee.bp_name ELSE '' END AS bp_name FROM fct_quotation_cashflow fqc, fct_contract fc, sys_code_b scb, sys_code_value_b scvb, vat_invoice_profile_dtl vipd, fnd_tax_type_code fttc, hls_cashflow_item hci, ( SELECT fpb.project_id, hbm.bp_id, hbm.bp_name, hbm.three_certificates, hbm.register_cert_num, hbm.tax_registry_num, hbm.invoice_bp_address_phone_num, hbm.invoice_bp_bank_account, hbm.invoice_title FROM fct_project_bp fpb JOIN hls_bp_master hbm ON fpb.bp_id= hbm.bp_id WHERE fpb.interest_repayment_party='Y') interest, ( SELECT fpb.project_id, hbm.bp_id, hbm.bp_name, hbm.three_certificates, hbm.register_cert_num, hbm.tax_registry_num, hbm.invoice_bp_address_phone_num, hbm.invoice_bp_bank_account, hbm.invoice_title FROM fct_project_bp fpb JOIN hls_bp_master hbm ON fpb.bp_id= hbm.bp_id WHERE fpb.use_fee_repayment_party='Y') fee WHERE fqc.quotation_cashflow_id IN
#{item}
AND scb.CODE = 'VAT.INVOICE_KIND' AND scb.CODE_ID = scvb.CODE_ID AND scvb.VALUE= vipd.invoice_kind AND fqc.contract_id = fc.contract_id AND fqc.cf_item = ( case when vipd.cf_item = 101 then 1 else vipd.cf_item end) AND fqc.cf_type=hci.cf_type AND fqc.cf_item = hci.cf_item AND fttc.tax_type_code = vipd.tax_type_code AND fttc.company_id = fc.company_id AND interest.project_id=fc.project_id AND fee.project_id=fc.project_id

select tt.*,t2.bs_cf_item,t2.merge_rental_flag,t2.invoice_kind,t2.invoice_kind_desc from ( SELECT t1.*, t1.write_off_due_amount total_amount, t1.write_off_interest total_interest, t1.write_off_principal total_principal, cc.business_type, cc.division, cc.sign_date, cc.billing_profile, ( SELECT max(bp.bp_id) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) bp_id, ( SELECT max(bp.bp_name) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) bp_name, ( SELECT max(bp.taxpayer_type) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) taxpayer_type, ( SELECT max(bp.tax_registry_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_tax_registry_num, ( SELECT max(bp.invoice_bp_address_phone_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_address_phone_num, ( SELECT max(bp.invoice_bp_bank_account) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_bank_account FROM con_contract cc, ( SELECT ccc.contract_id, ccc.cashflow_id, ccc.cf_item, sum( nvl(cwo.write_off_due_amount, 0) ) write_off_due_amount, SUm( nvl(cwo.write_off_interest, 0) ) write_off_interest, sum( nvl(cwo.write_off_principal, 0) ) write_off_principal, (@i:=@i+1) as ranks FROM con_contract_cashflow ccc, csh_write_off cwo, csh_transaction ct, (select @i:=0) as it WHERE ccc.cashflow_id = cwo.cashflow_id AND cwo.reversed_flag = 'N' AND cwo.csh_transaction_id = ct.transaction_id AND ct.transaction_type in ('RECEIPT','ADVANCE_RECEIPT') AND ccc.write_off_flag != 'NOT' AND ccc.billing_status != 'FULL' AND ct.reversed_flag = 'N'
and ccc.cashflow_id in
#{item}
GROUP BY ccc.cashflow_id ) t1 WHERE cc.contract_id = t1.contract_id AND cc.contract_status != 'NEW' AND cc.company_id = #{companyId} GROUP BY t1.cashflow_id ORDER BY t1.ranks ASC ) tt , ( select case hipd.cf_item when 100 then 1 when 101 then 1 else hipd.cf_item end as cf_item , hipd.cf_item as bs_cf_item , hipd.invoice_profile as invoice_profile, hipd.merge_rental_flag as merge_rental_flag ,hipd.invoice_kind as invoice_kind, (SELECT scv.MEANING FROM sys_code_b scb,sys_code_value_b scv WHERE scb.CODE = 'VAT.INVOICE_KIND' AND scb.CODE_ID = scv.CODE_ID and scv.value = hipd.invoice_kind) as invoice_kind_desc from vat_invoice_profile hip, vat_invoice_profile_dtl hipd where hip.invoice_profile=hipd.invoice_profile AND hipd.invoice_kind != 'RECEIPT' ) t2 where tt.cf_item = t2.cf_item and tt.billing_profile = t2.invoice_profile

SELECT t1.*, t2.invoice_kind, t2.invoice_kind_desc FROM ( SELECT t1.*, t1.write_off_due_amount total_amount, t1.write_off_interest total_interest, t1.write_off_principal total_principal, cc.business_type, cc.division, cc.sign_date, cc.billing_profile, (@i :=@i + 1) AS ranks, ( SELECT max(bp.bp_id) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_id, ( SELECT max(bp.bp_name) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_name, ( SELECT max(bp.taxpayer_type) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) taxpayer_type, ( SELECT max(bp.tax_registry_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_tax_registry_num, ( SELECT max(bp.invoice_bp_address_phone_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_address_phone_num, ( SELECT (bp.invoice_bp_bank_account) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_bank_account FROM con_contract cc, ( SELECT ccc.contract_id, wm_concat(ccc.cashflow_id) cashflow_ids, ccc.cf_item, sum( nvl(cwo.write_off_due_amount, 0) ) write_off_due_amount, SUm( nvl(cwo.write_off_interest, 0) ) write_off_interest, sum( nvl(cwo.write_off_principal, 0) ) write_off_principal FROM con_contract_cashflow ccc, csh_write_off cwo, csh_transaction ct WHERE ccc.cashflow_id = cwo.cashflow_id AND cwo.reversed_flag = 'N' AND cwo.csh_transaction_id = ct.transaction_id AND ct.transaction_type = 'RECEIPT' AND ccc.write_off_flag != 'NOT' AND ccc.billing_status != 'FULL' AND ct.reversed_flag = 'N'
and ccc.cashflow_id in
#{item}
GROUP BY ccc.contract_id ) t1, (SELECT @i := 0) AS it WHERE cc.contract_id = t1.contract_id AND cc.contract_status != 'NEW' AND cc.company_id = #{companyId} GROUP BY cc.contract_id ORDER BY ranks ASC ) t1, ( SELECT DISTINCT CASE hipd.cf_item WHEN 100 THEN 1 WHEN 101 THEN 1 ELSE hipd.cf_item END AS cf_item, hipd.invoice_profile AS invoice_profile, hipd.invoice_kind as invoice_kind, (SELECT scv.MEANING FROM sys_code_b scb,sys_code_value_b scv WHERE scb.CODE = 'VAT.INVOICE_KIND' AND scb.CODE_ID = scv.CODE_ID and scv.value = hipd.invoice_kind) as invoice_kind_desc FROM vat_invoice_profile hip, vat_invoice_profile_dtl hipd WHERE hip.invoice_profile = hipd.invoice_profile AND hipd.invoice_kind != 'RECEIPT' AND hip.enabled_flag = 'Y' ) t2 WHERE t1.cf_item = t2.cf_item AND t1.billing_profile = t2.invoice_profile

select t1.*,t2.invoice_kind,t2.invoice_kind_desc from ( select v.ranks, v.bp_id, v.bp_name, wm_concat(v.cashflow_id) cashflow_ids, SUM(v.total_amount) total_amount, SUM(v.total_interest) total_interest, SUM(v.total_principal) total_principal, SUM(v.write_off_due_amount) write_off_due_amount, SUM(v.write_off_principal) write_off_principal, SUM(v.write_off_interest) write_off_interest, v.business_type, v.division, v.sign_date, v.bp_address_phone_num, v.bp_bank_account, v.taxpayer_type, v.cf_item, v.bp_tax_registry_num, v.billing_profile from ( SELECT t1.*, t1.write_off_due_amount total_amount, t1.write_off_interest total_interest, t1.write_off_principal total_principal, cc.business_type, cc.division, cc.sign_date, cc.billing_profile, (@i:=@i+1) as ranks, ( SELECT max(bp.bp_id) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_id, ( SELECT max(bp.bp_name) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_name, ( SELECT max(bp.taxpayer_type) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) taxpayer_type, ( SELECT max(bp.tax_registry_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) bp_tax_registry_num, ( SELECT max(bp.invoice_bp_address_phone_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_address_phone_num, ( SELECT max(bp.invoice_bp_bank_account) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_bank_account FROM con_contract cc, ( SELECT ccc.contract_id, wm_concat(ccc.cashflow_id) cashflow_id, ccc.cf_item, sum( nvl(cwo.write_off_due_amount, 0) ) write_off_due_amount, SUm( nvl(cwo.write_off_interest, 0) ) write_off_interest,
sum( nvl(cwo.write_off_principal, 0) ) write_off_principal FROM con_contract_cashflow ccc, csh_write_off cwo, csh_transaction ct WHERE ccc.cashflow_id = cwo.cashflow_id AND cwo.reversed_flag = 'N' AND cwo.csh_transaction_id = ct.transaction_id AND ct.transaction_type = 'RECEIPT' AND ccc.write_off_flag != 'NOT' AND ccc.billing_status != 'FULL' AND ct.reversed_flag = 'N'
and ccc.cashflow_id in
#{item}
GROUP BY ccc.contract_id ) t1, (select @i:=0) as it WHERE cc.contract_id = t1.contract_id AND cc.company_id = #{companyId} AND cc.contract_status != 'NEW' order by cc.contract_id )v GROUP BY v.bp_id ORDER BY v.ranks ASC ) t1 , ( SELECT DISTINCT CASE hipd.cf_item WHEN 100 THEN 1 WHEN 101 THEN 1 ELSE hipd.cf_item END AS cf_item, hipd.invoice_profile AS invoice_profile, hipd.invoice_kind as invoice_kind, (SELECT scv.MEANING FROM sys_code_b scb,sys_code_value_b scv WHERE scb.CODE = 'VAT.INVOICE_KIND' AND scb.CODE_ID = scv.CODE_ID and scv.value = hipd.invoice_kind) as invoice_kind_desc FROM vat_invoice_profile hip, vat_invoice_profile_dtl hipd WHERE hip.invoice_profile = hipd.invoice_profile AND hipd.invoice_kind != 'RECEIPT' AND hip.enabled_flag = 'Y' ) t2 WHERE t1.cf_item = t2.cf_item AND t1.billing_profile = t2.invoice_profile

SELECT aih.invoice_hd_id, aih.document_number, aih.invoice_date, aih.invoice_number, aih.invoice_kind, ( SELECT scvb.description FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scb. CODE = 'VAT.INVOICE_KIND' AND scvb. VALUE = aih.invoice_kind ) AS invoice_kind_desc, aih.bp_name, aih.bp_tax_registry_num, aih.bp_bank_account, aih.total_amount, aih.net_amount, aih.tax_amount FROM acr_invoice_hd aih, hls_bp_master hbm
aih.bp_id = hbm.bp_id and aih.reversed_flag = 'N' and aih.invoice_status != 'NEW'
and (aih.document_number like concat(concat('%',#{invoiceNumber}),'%'))
and (aih.bp_name like concat(concat('%',#{bpInfo}),'%') or aih.bp_tax_registry_num like concat(concat('%',#{bpInfo}),'%') or ((select max(hbm.bp_code) from hls_bp_master hbm where hbm.bp_id = aih.bp_id ) like concat(concat('%',#{bpInfo}),'%')) )
and aih.total_amount >= #{totalAmountFrom}
and aih.total_amount <= #{totalAmountTo}
and aih.invoice_kind in
#{item}

SELECT aih.invoice_hd_id, aih.document_number, aih.invoice_date, aih.invoice_kind, ( SELECT scvb.description FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scb. CODE = 'VAT.INVOICE_KIND' AND scvb. VALUE = aih.invoice_kind ) AS invoice_kind_desc, aih.bp_name, aih.bp_tax_registry_num, aih.bp_bank_account, aih.total_amount, aih.net_amount, aih.tax_amount FROM acr_invoice_hd aih
aih.reversed_flag = 'W'
and (aih.document_number like concat(concat('%',#{bpInfo}),'%') or aih.bp_name like concat(concat('%',#{bpInfo}),'%') or aih.bp_tax_registry_num like concat(concat('%',#{bpInfo}),'%') or ((select max(hbm.bp_code) from hls_bp_master hbm where hbm.bp_id = aih.bp_id ) like concat(concat('%',#{bpInfo}),'%')) )
and (aih.invoice_number like concat(concat('%',#{invoiceNumber}),'%'))
and aih.total_amount >= #{totalAmountFrom}
and aih.total_amount <= #{totalAmountTo}
and aih.invoice_kind in
#{item}

SELECT aih.invoice_hd_id, aih.document_number, aih.invoice_date, aih.invoice_kind, ( SELECT scvb.description FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scb. CODE = 'VAT.INVOICE_KIND' AND scvb. VALUE = aih.invoice_kind ) AS invoice_kind_desc, aih.bp_name, aih.bp_tax_registry_num, aih.bp_bank_account, aih.total_amount, aih.net_amount, aih.tax_amount FROM acr_invoice_hd aih, hls_bp_master hbm
aih.reversed_flag = 'N' AND aih.bp_id = hbm.bp_id
and aih.company_id = #{companyId}
and aih.invoice_hd_id in
#{item}
and (aih.invoice_number like concat(concat('%',#{invoiceNumber}),'%'))
and (aih.bp_name like concat(concat('%',#{bpInfo}),'%') or aih.bp_tax_registry_num like concat(concat('%',#{bpInfo}),'%') or ((select max(hbm.bp_code) from hls_bp_master hbm where hbm.bp_id = aih.bp_id ) like concat(concat('%',#{bpInfo}),'%')) )
and aih.total_amount >= #{totalAmountFrom}
and aih.total_amount <= #{totalAmountTo}
and aih.invoice_kind in
#{item}

SELECT * FROM( SELECT aid.invoice_hd_id, aid.invoice_date, (select scvb.description from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'VAT.INVOICE_KIND' and scvb.value = aid.invoice_kind) as invoice_kind_desc, aid.invoice_kind, aid.bp_name, aid.company_id, aid.bp_tax_registry_num, aid.bp_address_phone_num, aid.bp_bank_account, aid.total_amount, aid.net_amount, aid.tax_amount, aid.reversed_flag, (select max(nvl(l.tax_type_rate,0)) from acr_invoice_ln l where l.invoice_hd_id = aid.invoice_hd_id)tax_type_rate FROM acr_invoice_hd aid where aid.invoice_kind !='RECEIPT'
) aid
aid.reversed_flag = 'N' and aid.company_id = #{companyId}
and aid.invoice_date between sysdate and #{invoiceDate}
and aid.invoice_kind = #{invoiceKind}
and aid.invoice_date between ADDDATE(sysdate,INTERVAL -7 day) and sysdate
and aid.invoice_date between ADDDATE(sysdate,INTERVAL -1 MONTH) and sysdate
and aid.invoice_date between ADDDATE(sysdate,INTERVAL -3 MONTH) and sysdate
and aid.tax_type_rate in
#{item}
order by aid.invoice_date desc

select t1.total_amount * t2.tax_type_rate as tax_amount, t1.total_amount - (t1.total_amount * t2.tax_type_rate) as net_amount,
t2.invoice_kind_desc, t2.invoice_kind, t2.merge_rental_flag, t2.bs_cf_item, t2.bs_cf_item_desc, t2.taxable_service_name, t2.tax_type_rate, t1.* from (SELECT ccc.contract_id, ccc.cashflow_id, ccc.cf_item, ccc.cf_type, nvl(ccc.due_amount, 0) due_amount, nvl(ccc.principal, 0) principal, nvl(ccc.interest, 0) interest, nvl(ccc.received_amount, 0) received_amount, nvl(ccc.received_principal, 0) received_principal, nvl(ccc.received_interest, 0) received_interest, (nvl(ccc.due_amount, 0) - nvl(ccc.billing_amount, 0)) as total_amount, nvl(ccc.billing_principal, 0) billing_principal, nvl(ccc.billing_interest, 0) billing_interest, ccc.times, ( SELECT ci.description FROM hls_cashflow_item ci WHERE ci.cf_item = ccc.cf_item AND ci.cf_type = ccc.cf_type ) cf_item_desc, ( SELECT ci.description FROM hls_cashflow_item ci WHERE ci.cf_item = ccc.cf_item AND ci.cf_type = ccc.cf_type ) product_name, ( SELECT max(bp.bp_id) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) bp_id, ( SELECT max(bp.bp_name) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id
) bp_name, ( SELECT max(bp.tax_registry_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) bp_tax_registry_num, ( SELECT max(bp.invoice_bp_address_phone_num) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) bp_address_phone_num, ( SELECT max(bp.invoice_bp_bank_account) FROM con_contract_tenant cct, hls_bp_master bp WHERE cct.contract_id = cc.contract_id AND cct.tenant_bp_id = bp.bp_id ) bp_bank_account, cc.billing_profile FROM con_contract cc, con_contract_cashflow ccc WHERE cc.contract_id = ccc.contract_id AND cc.contract_status != 'NEW' AND ccc.billing_status != 'FULL'
AND cc.company_id = #{companyId}
AND ccc.cashflow_id in
#{item}
) t1, (SELECT CASE hipd.cf_item WHEN 100 THEN 1 WHEN 101 THEN 1 ELSE hipd.cf_item END AS cf_item, hipd.cf_item AS bs_cf_item, ( SELECT max(ci.description) FROM hls_cashflow_item ci WHERE ci.cf_item = hipd.cf_item ) bs_cf_item_desc, hipd.invoice_profile AS invoice_profile, hipd.merge_rental_flag AS merge_rental_flag, hipd.invoice_kind AS invoice_kind, hipd.taxable_service_name as taxable_service_name, ( SELECT scv.MEANING FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'VAT.INVOICE_KIND' AND scb.CODE_ID = scv.CODE_ID AND scv.VALUE = hipd.invoice_kind ) AS invoice_kind_desc, ( SELECT max(fttc.tax_type_rate) FROM fnd_tax_type_code fttc WHERE fttc.tax_type_code = hipd.tax_type_code ) AS tax_type_rate FROM vat_invoice_profile hip, vat_invoice_profile_dtl hipd WHERE hip.invoice_profile = hipd.invoice_profile AND hipd.invoice_kind != 'RECEIPT'
and hipd.cf_item in
#{item2}
)t2 where t1.cf_item = t2.cf_item and t1.billing_profile = t2.invoice_profile

SELECT aih.*, (select scvb.description from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'VAT.INVOICE_KIND' and scvb.value = aih.invoice_kind) as invoice_kind_desc FROM ACR_INVOICE_HD aih where 1=1
and aih.invoice_date between date_sub(curdate(), interval #{time} day_second) and curdate()
and aih.invoice_kind = #{invoiceKind}

select * from (SELECT cwo.write_off_id, cwo.write_off_date, ( SELECT scvb.description FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scb. CODE = 'CSH.WRITE_OFF_TYPE' AND scvb.VALUE = cwo.write_off_type ) AS write_off_type, cc.contract_number, ccc.times, cc.contract_id, (SELECT hci.description FROM hls_cashflow_item hci WHERE hci.cf_item = ccc.cf_item) AS description, nvl(cwo.write_off_due_amount,0) as write_off_due_amount, nvl(cwo.write_off_principal,0) as write_off_principal, nvl(cwo.write_off_interest,0) as write_off_interest, cwo.LAST_UPDATE_DATE, (select su.DESCRIPTION from sys_user su where su.USER_ID = cwo.LAST_UPDATED_BY) as userName, cwo.write_off_doc_category FROM csh_write_off cwo, con_contract cc, con_contract_cashflow ccc WHERE cwo.contract_id = cc.contract_id AND cwo.cashflow_id = ccc.cashflow_id UNION SELECT cwo.write_off_id, cwo.write_off_date, ( SELECT scvb.description FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scb. CODE = 'CSH.WRITE_OFF_TYPE' AND scvb.VALUE = cwo.write_off_type ) AS write_off_type, cc.contract_number, ccc.times, cc.contract_id, (SELECT hci.description FROM hls_cashflow_item hci WHERE hci.cf_item = ccc.cf_item) AS description, nvl(cwo.write_off_due_amount,0) as write_off_due_amount, nvl(cwo.write_off_principal,0) as write_off_principal, nvl(cwo.write_off_interest,0) as write_off_interest, cwo.LAST_UPDATE_DATE, (select su.DESCRIPTION from sys_user su where su.USER_ID = cwo.LAST_UPDATED_BY) as userName, cwo.write_off_doc_category FROM csh_write_off cwo, fct_contract cc, fct_quotation_cashflow ccc WHERE cwo.contract_id = cc.contract_id AND cwo.cashflow_id = ccc.quotation_cashflow_id) t1 where 1=1
AND t1.write_off_id = #{writeOffId}
AND t1.write_off_doc_category = #{writeOffDocCategory}

select * from acr_invoice_hd

    1=1

    and invoice_hd_id = #{invoiceHdId}

select aih.invoice_hd_id, aih.invoice_status, aih.invoice_code, aih.invoice_number, aih.bp_tax_registry_num, (select scvb.description from sys_code_b scb,sys_code_value_b scvb where scb.code_id=scvb.code_id and scb.code='VAT.INVOICE_KIND' and scvb.value=aih.invoice_kind) as invoice_kind_desc, ail.invoice_ln_id, aih.document_number, aih.invoice_date, (select hbm.bp_code from hls_bp_master hbm where hbm.bp_id=aih.bp_id) as bp_code, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=aih.bp_id) as bp_name, ( SELECT hbm.SOCIAL_CREDIT_CODE FROM hls_bp_master hbm WHERE hbm.bp_id = aih.bp_id ) AS SOCIAL_CREDIT_CODE, aih.bp_address_phone_num, aih.bp_bank_account, aih.description, AIL.PRODUCT_NAME, ail.SPECIFICATION, AIL.QUANTITY, AIL.TOTAL_AMOUNT, AIL.TAX_TYPE_RATE, AIL.TAX_AMOUNT, AIL.UOM, AIL.PRICE, '0' as tax_type_num, (select ccc.contract_id from con_contract_cashflow ccc where ccc.cashflow_id = aild.cashflow_id ) as contract_id from acr_invoice_hd aih, acr_invoice_ln ail, acr_invoice_ln_dt aild where aih.invoice_hd_id = ail.invoice_hd_id and ail.invoice_ln_id = aild.invoice_ln_id
and aih.invoice_hd_id = #{invoiceHdId}
and aih.invoice_status = #{invoiceStatus}
and aih.invoice_hd_id IN
#{item}

select tem.* from ( ( select fqc.contract_id, fc.contract_name, fc.contract_number, fqc.times, fqc.due_date, (SELECT f.approval_number FROM prj_project f WHERE f.project_id = fc.project_id ) AS contract_content_number,
(case when fc.business_type='LEASE' and fqc.cf_item=1 then '本金' when fc.business_type='LEASE' and fqc.cf_item=2 then '首付款' when fc.business_type='OPERATING_LEASE' and fqc.cf_item=1 then '租金' when fc.business_type='LEASEBACK' and fqc.cf_item=1 then '利息' else hci.description end ) as cf_item_desc, aih.invoice_hd_id, aih.invoice_status, aih.invoice_number, aih.invoice_code, (select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id=scvb.code_id and scb.code='VAT.INVOICE_KIND' and scvb.value=aih.invoice_kind) as invoice_kind_desc, (select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id=scvb.code_id and scb.code='VAT.INVOICE_STATUS' and scvb.value=aih.invoice_status) as invoice_status_n, aih.confirm_status, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_CONFIRM_STATUS' AND aih.confirm_status = v.code_value ) confirm_status_n, ail.invoice_ln_id, aih.document_number, aih.invoice_date, aih.tax_invoice_date, (select hbm.bp_code from hls_bp_master hbm where hbm.bp_id=aih.bp_id) as bp_code, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=aih.bp_id) as bp_name, ( SELECT hbm.SOCIAL_CREDIT_CODE FROM hls_bp_master hbm WHERE hbm.bp_id = aih.bp_id ) AS bp_tax_registry_num, aih.bp_address_phone_num, aih.bp_bank_account, aih.description, ail.product_name, ail.specification, ail.uom, ail.quantity, ail.price, ail.total_amount, ail.tax_type_rate, ail.tax_amount, '0' as tax_type_num from acr_invoice_hd aih, acr_invoice_ln ail, acr_invoice_ln_dt aild, hls_cashflow_item hci, con_contract_cashflow fqc, con_contract fc where aih.invoice_hd_id = ail.invoice_hd_id and ail.invoice_ln_id = aild.invoice_ln_id AND hci.cf_type = fqc.cf_type AND hci.cf_item = fqc.cf_item and fqc.cashflow_id = aild.cashflow_id and fc.contract_id = fqc.contract_id and aih.reversed_flag in ('N', 'W')
and aih.invoice_hd_id = #{invoiceHdId}
and aih.invoice_status = #{invoiceStatus}
and to_date(to_char(aih.invoice_date,'yyyy-MM-dd'),'yyyy-mm-dd hh24:mi:ss') >= to_date(#{dateFrom},'yyyy-mm-dd hh24:mi:ss')
and to_date(to_char(aih.invoice_date,'yyyy-MM-dd'),'yyyy-mm-dd hh24:mi:ss') <= to_date(#{dateTo},'yyyy-mm-dd hh24:mi:ss')
and aih.invoice_kind in
#{item}
and aih.company_id = #{companyId} ) ) tem where 1=1
and tem.invoice_kind_desc = #{invoiceKindDesc}
order by tem.invoice_date DESC

select v.* from ( select aih.invoice_hd_id, aih.invoice_kind, aih.document_number, aih.billing_way, aih.invoice_code, aih.invoice_number, aih.invoice_date, aih.bp_name, aih.bp_tax_registry_num, aih.bp_address_phone_num, aih.bp_bank_account, ail.NET_AMOUNT, ail.TAX_AMOUNT, ail.product_name, aih.invoice_status, aih.receipt_flag, aih.red_invoice_notice, aih.invoice_period, aih.total_amount, aih.dzfp_url, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_KIND' AND aih.invoice_kind = v.code_value ) invoice_kind_n, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = aih.bp_id ) bp_id_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.BILLING_WAY' AND aih.billing_way = v.code_value ) billing_way_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_STATUS' AND aih.invoice_status = v.code_value ) invoice_status_n, aih.confirm_status, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_CONFIRM_STATUS' AND aih.confirm_status = v.code_value ) confirm_status_n, ( SELECT su.description FROM sys_user su WHERE su.user_id = aih.created_by ) created_by_n, ( SELECT su.description FROM sys_user su WHERE su.user_id = aih.confirmed_by ) confirmed_by_n, aih.reversed_flag, aih.creation_date, (case when (select count(1) from acr_invoice_ln ln, acr_invoice_ln_dt dt, con_contract_cashflow cf where ln.invoice_hd_id = aih.invoice_hd_id and dt.invoice_ln_id = ln.invoice_ln_id and cf.cashflow_id = dt.cashflow_id and (cf.write_off_flag = 'NOT' or cf.write_off_flag = 'PARTIAL')) = 0 then '核销' when (select count(1) from acr_invoice_ln ln, acr_invoice_ln_dt dt, con_contract_cashflow cf where ln.invoice_hd_id = aih.invoice_hd_id and dt.invoice_ln_id = ln.invoice_ln_id and cf.cashflow_id = dt.cashflow_id and (cf.write_off_flag = 'FULL' or cf.write_off_flag = 'PARTIAL')) = 0 then '未核销' else '部分核销' end) write_off_flag_n, aih.description, contract.contract_number, contract.cf_item, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'JC.BILL_ITEM' AND to_char(contract.cf_item) = v.code_value ) cf_item_n, contract.times, contract.due_date, contract.contract_name, ( case when contract.business_type='LEASE' and contract.cf_item=1 then contract.principal when contract.business_type='LEASE' and contract.cf_item=2 then contract.due_amount when contract.business_type='OPERATING_LEASE' and contract.cf_item=1 then contract.due_amount when contract.business_type='LEASEBACK' and contract.cf_item=1 then contract.interest when contract.cf_item in (3,4,8,10) then contract.due_amount else 0 end ) as due_amount, ( case when contract.business_type = 'LEASE' and contract.cf_item = 1 then contract.principal - nvl(contract.billing_principal,0) when contract.business_type = 'LEASE' and contract.cf_item = 2 then contract.due_amount - nvl(contract.billing_amount,0) when contract.business_type = 'OPERATING_LEASE' and contract.cf_item = 1 then contract.due_amount - nvl(contract.billing_amount,0) when contract.business_type = 'LEASEBACK' and contract.cf_item = 1 then contract.interest - nvl(contract.billing_amount,0) when contract.cf_item in (3, 4, 8,10) then contract.due_amount - nvl(contract.billing_amount,0) else 0 end ) as billing_amount from acr_invoice_hd aih left join (select ln.INVOICE_HD_ID,wm_concat(distinct ln.PRODUCT_NAME) as PRODUCT_NAME,SUM(ln.NET_AMOUNT) as NET_AMOUNT,SUM(ln.TAX_AMOUNT) as TAX_AMOUNT from acr_invoice_ln ln group by ln.INVOICE_HD_ID ) ail on aih.INVOICE_HD_ID = ail.INVOICE_HD_ID LEFT JOIN ( SELECT ln.INVOICE_HD_ID, cf.cf_item, cf.times, cf.due_date, cf.principal, cf.due_amount, cf.interest, cf.billing_principal, cf.billing_amount, cc.contract_name, cc.business_type, wm_concat(DISTINCT pp.contract_number ) AS contract_number FROM acr_invoice_ln ln, acr_invoice_ln_dt dt, con_contract_cashflow cf, con_contract cc, prj_project pp WHERE dt.invoice_ln_id = ln.invoice_ln_id AND cf.cashflow_id = dt.cashflow_id AND cc.CONTRACT_ID = cf.CONTRACT_ID AND cc.PROJECT_ID = pp.PROJECT_ID GROUP BY ln.INVOICE_HD_ID, cf.cf_item, cf.times, cf.due_date, cf.principal, cf.due_amount, cf.interest, cf.billing_principal, cf.billing_amount, cc.contract_name, cc.business_type ) contract on contract.invoice_hd_id = aih.invoice_hd_id
1=1
and aih.created_by = #{request.userId}
)v
1=1
and (v.invoice_status in ('IMPORTED','NEGATIVE','RED','CANCEL') or v.invoice_status='NEW' and v.total_amount <0 )
and v.invoice_status in ('NEW') and v.reversed_flag = 'N'
and v.document_number LIKE concat('%', concat(#{documentNumber}, '%'))
and v.invoice_kind = #{invoiceKind}
and v.billing_way = #{billingWay}
and v.invoice_code LIKE concat('%', concat(#{invoiceCode}, '%'))
and v.invoice_number LIKE concat('%', concat(#{invoiceNumber}, '%'))
and to_char(v.invoice_date,'yyyy-MM-dd') >= #{invoiceDateFrom}
and to_char(v.invoice_date,'yyyy-MM-dd') <= #{invoiceDateTo}
and v.bp_id_n like concat('%',concat(#{bpIdN},'%'))
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.net_amount >= #{netAmountFrom}
and v.net_amount <= #{netAmountTo}
and v.total_amount >= #{totalAmountFrom}
and v.total_amount <= #{totalAmountTo}
and v.invoice_status = #{invoiceStatus}
and v.created_by_n like concat('%',concat(#{createdByN},'%'))
order by v.creation_date desc

select v.* from ( select aih.invoice_hd_id, aih.source_invoice_header_id, aih.invoice_kind, aih.document_number, aih.billing_way, aih.invoice_code, aih.invoice_number, aih.invoice_date, aih.bp_name, aih.bp_tax_registry_num, aih.bp_address_phone_num, aih.bp_bank_account, aih.net_amount, aih.tax_amount, aih.invoice_status, aih.receipt_flag, aih.red_invoice_notice, aih.invoice_period, aih.total_amount, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_KIND' AND aih.invoice_kind = v.code_value ) invoice_kind_n, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = aih.bp_id ) bp_id_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.BILLING_WAY' AND aih.billing_way = v.code_value ) billing_way_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_STATUS' AND aih.invoice_status = v.code_value ) invoice_status_n, aih.confirm_status, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'VAT.INVOICE_CONFIRM_STATUS' AND aih.confirm_status = v.code_value ) confirm_status_n, ( SELECT su.description FROM sys_user su WHERE su.user_id = aih.created_by ) created_by_n, ( SELECT su.description FROM sys_user su WHERE su.user_id = aih.confirmed_by ) confirmed_by_n, aih.reversed_flag, aih.creation_date, (case when (select count(1) from acr_invoice_ln ln, acr_invoice_ln_dt dt, con_contract_cashflow cf where ln.invoice_hd_id = aih.invoice_hd_id and dt.invoice_ln_id = ln.invoice_ln_id and cf.cashflow_id = dt.cashflow_id and (cf.write_off_flag = 'NOT' or cf.write_off_flag = 'PARTIAL')) = 0 then '核销' when (select count(1) from acr_invoice_ln ln, acr_invoice_ln_dt dt, con_contract_cashflow cf where ln.invoice_hd_id = aih.invoice_hd_id and dt.invoice_ln_id = ln.invoice_ln_id and cf.cashflow_id = dt.cashflow_id and (cf.write_off_flag = 'FULL' or cf.write_off_flag = 'PARTIAL')) = 0 then '未核销' else '部分核销' end) write_off_flag_n, aih.description, aih.dzfp_Url from acr_invoice_hd aih )v
1=1
and v.invoice_hd_id =#{invoiceHdId}
and v.document_number LIKE concat('%', concat(#{documentNumber}, '%'))
and v.invoice_kind = #{invoiceKind}
and v.billing_way = #{billingWay}
and v.invoice_code LIKE concat('%', concat(#{invoiceCode}, '%'))
and v.invoice_number LIKE concat('%', concat(#{invoiceNumber}, '%'))
and v.invoice_date >= #{invoiceDateFrom}
and v.invoice_date <= #{invoiceDateTo}
and v.bp_id_n like concat('%',concat(#{bpIdN},'%'))
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.net_amount >= #{netAmountFrom}
and v.net_amount <= #{netAmountTo}
and v.total_amount >= #{totalAmountFrom}
and v.total_amount <= #{totalAmountTo}
and v.invoice_status = #{invoiceStatus}
and v.created_by_n like concat('%',concat(#{createdByN},'%'))
order by v.creation_date desc

select v.* from (SELECT aih.billing_method, aih.invoice_hd_id, aih.document_number, nvl(aih.handover_date, sysdate) AS handover_date, (case when aih.handover_person is NULL then (select distinct pp.host_unit_id from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) else aih.handover_person end) AS handover_person, (case when aih.handover_person is NULL then (SELECT distinct fou.unit_name FROM fnd_org_unit fou, con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid WHERE fou.unit_id = pp.host_unit_id and aih.invoice_hd_id = ail.invoice_hd_id AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.cashflow_id = aid.cashflow_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) else (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = aih.handover_person) end) AS handover_person_n, (select distinct cc.contract_number from con_contract_cashflow ccc, con_contract cc, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id) contract_number,
aih.invoice_date, aih.invoice_number, aih.bp_name, aih.total_amount, (select distinct max(ail.tax_type_rate) from acr_invoice_ln ail where ail.invoice_hd_id = aih.invoice_hd_id )tax_type_rate,
(case when aih.handover_status is NULL then 'NOT_TRANSFER' else aih.handover_status end) AS handover_status, (SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'INVOICE_HANDOVER_STATUS' AND scv.value = (case when aih.handover_status is NULL then 'NOT_TRANSFER' else aih.handover_status end)) AS handover_status_n, (select distinct pp.host_project_manager from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) as host_project_manager, (SELECT distinct su.description FROM sys_user su, con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid WHERE su.user_id = pp.host_project_manager and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.cashflow_id = aid.cashflow_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) AS HOST_MANAGER, (select distinct pp.host_unit_id from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) as host_unit_id, (select distinct pp.host_unit_id from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) as unit_id,
(SELECT distinct fou.unit_name FROM fnd_org_unit fou, con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid
WHERE fou.unit_id = pp.host_unit_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.cashflow_id = aid.cashflow_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) AS HOST_PARTMENT
FROM acr_invoice_hd aih where aih.invoice_status = 'IMPORTED' ORDER BY aih.document_number DESC) v
and v.document_number like #{documentNumber}
and to_char(v.invoice_date,'yyyy-MM-dd') > #{invoiceDateFrom}
and to_char(v.invoice_date,'yyyy-MM-dd') < #{invoiceDateTo}
and v.bp_name like #{bpName}
and v.handover_status = #{handoverStatus}
and v.contract_number like #{contractNumber}
and v.unit_id = #{hostPartment}
and v.host_partment like #{hostPartmentN}
and v.billing_method = #{billingMethod}

select v.* from (SELECT aih.billing_method, aih.invoice_hd_id, aih.document_number, nvl(aih.handover_date, sysdate) AS handover_date, (case when aih.handover_person is NULL then (select distinct pp.host_unit_id from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) else aih.handover_person end) AS handover_person, (case when aih.handover_person is NULL then (SELECT distinct fou.unit_name FROM fnd_org_unit fou, con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid WHERE fou.unit_id = pp.host_unit_id and aih.invoice_hd_id = ail.invoice_hd_id AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.cashflow_id = aid.cashflow_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) else (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = aih.handover_person) end) AS handover_person_n, (select distinct cc.contract_number from con_contract_cashflow ccc, con_contract cc, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id) contract_number,
aih.invoice_date, aih.invoice_number, aih.bp_name, aih.total_amount, (select distinct max(ail.tax_type_rate) from acr_invoice_ln ail where ail.invoice_hd_id = aih.invoice_hd_id) tax_type_rate,
(case when aih.handover_status is NULL then 'NOT_TRANSFER' else aih.handover_status end) AS handover_status, (SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'INVOICE_HANDOVER_STATUS' AND scv.value = ( case when aih.handover_status is NULL then 'NOT_TRANSFER' else aih.handover_status end)) AS handover_status_n,
(select distinct pp.host_project_manager from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) as host_project_manager, (SELECT distinct su.description FROM sys_user su, con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid WHERE su.user_id = pp.host_project_manager and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.cashflow_id = aid.cashflow_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) AS HOST_MANAGER, (select distinct pp.host_unit_id from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) as host_unit_id, (select distinct pp.host_unit_id from con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid where ccc.cashflow_id = aid.cashflow_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) as unit_id,
(SELECT distinct fou.unit_name FROM fnd_org_unit fou, con_contract_cashflow ccc, con_contract cc, prj_project pp, acr_invoice_ln ail, acr_invoice_ln_dt aid
WHERE fou.unit_id = pp.host_unit_id and aih.invoice_hd_id = ail.invoice_hd_id
AND ail.invoice_ln_id = aid.invoice_ln_id and ccc.cashflow_id = aid.cashflow_id and ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id) AS HOST_PARTMENT, aih.review_person FROM acr_invoice_hd aih where aih.invoice_status = 'IMPORTED' AND aih.handover_status IN ('TRANSFERING', 'TRANSFER_END') order by aih.document_number desc) v
and v.document_number like #{documentNumber}
and to_char(v.invoice_date,'yyyy-MM-dd') > #{invoiceDateFrom}
and DATE_FORMAT（v.invoice_date,'yyyy-MM-dd') < #{invoiceDateTo}
and v.bp_name like #{bpName}
and v.handover_status = #{handoverStatus}
and v.contract_number like #{contractNumber}
and v.host_partment = #{hostPartment}
and v.billing_method = #{billingMethod}

select * from (
select *
from acr_invoice_hd aih
where aih.billing_Way='1'
and aih.invoice_status not in('NEW','IMPORTED_FAILURE')
and aih.invoice_number is not null
/*and aih.dzfp_url is null */
) v


        and v.document_number =#{documentNumber}


        and v.invoice_hd_id =#{invoiceHdId}
